local player = game:GetService("Players").LocalPlayer
local toolName = "Building Tools"
local tool = player.Backpack:FindFirstChild(toolName) or player.Character:FindFirstChild(toolName)
local Event = tool.SyncAPI.ServerEndpoint

task.spawn(function()
local pt = Event:InvokeServer("CreatePart", "Normal", CFrame.new(-280, 201.5, 401.5), workspace)
    if typeof(pt) ~= "Instance" then pt = workspace:GetChildren()[#workspace:GetChildren()] end
    Event:InvokeServer("SyncResize",{{Part = pt,CFrame = pt.CFrame,Size = Vector3.new(21.6,12.2,0.6)}})
    Event:InvokeServer("SyncColor",{{Part = pt,UnionColoring = true,Color = Color3.fromRGB(74,82,98)}})
    Event:InvokeServer("SyncMaterial", {{Part = pt, Material = Enum.Material.Plastic, Reflectance = 0, Transparency = 0}})
    Event:InvokeServer("CreateLights", {{Part = pt, LightType = "PointLight"}})
    Event:InvokeServer("SyncLighting", {{Part = pt,LightType = "PointLight",Brightness = 0.5,Range = 16,Color = Color3.fromRGB(255, 255, 255),Shadows = false}})



end)

