    Event:InvokeServer("SyncResize",{{Part = pt,CFrame = pt.CFrame,Size = Vector3.new(2,0.6,2)}})
    Event:InvokeServer("SyncColor",{{Part = pt,UnionColoring = true,Color = Color3.fromRGB(112,114,129)}})
