    Event:InvokeServer("SyncResize",{{Part = pt,CFrame = pt.CFrame,Size = Vector3.new(10,1,12)}})
    Event:InvokeServer("SyncColor",{{Part = pt,UnionColoring = true,Color = Color3.fromRGB(163,162,165)}})
