                    Back = Enum.SurfaceType.Universal,
                    Right = Enum.SurfaceType.Universal,
                    Left = Enum.SurfaceType.Universal
                }
            }})
    Event:InvokeServer("SyncMaterial", {{Part = pt, Material = Enum.Material.Concrete, Reflectance = 0, Transparency = 0}})

end)

